{"path": "/private/tmp/prompt_matrix/runs_pro-x-flashprompt/workspaces/04/lib/parser.mbt", "content": "///| Parser: converts a token stream into a JSON value via line-oriented TOML parsing.

///|
enum Value {
  VString(String)
  VInteger(Int64)
  VBoolean(Bool)
  VArray(Array[Value])
}

///|
struct Parser {
  tokens : Array[Token]
  pos : Int
}

///|
fn new_parser(tokens : Array[Token]) -> Parser {
  { tokens, pos: 0 }
}

///|
fn current(self : Parser) -> Token {
  self.tokens[self.pos]
}

///|
fn advance(self : Parser) -> Parser {
  let mut p = self
  p.pos = p.pos + 1
  p
}

///|
fn skip_newlines(self : Parser) -> Parser {
  let mut p = self
  while p.current() is Newline {
    p = p.advance()
  }
  p
}

///|
fn parse_value_from_parser(self : Parser) -> (Value, Parser) raise TomlError {
  let tok = self.current()
  match tok {
    String(s) => (VString(s), self.advance())
    Integer(n) => (VInteger(n), self.advance())
    Boolean(b) => (VBoolean(b), self.advance())
    LBrace => {
      let mut p = self.advance()
      let mut arr = []
      p = p.skip_newlines()
      while p.current() isnot RBrace && p.current() isnot EOF {
        let result = parse_value_from_parser(p)
        let v = result.0
        p = result.1
        arr.push(v)
        p = p.skip_newlines()
        if p.current() is Comma {
          p = p.advance()
          p = p.skip_newlines()
        } else {
          break
        }
      }
      if p.current() isnot RBrace {
        raise TomlError::InvalidSyntax("expected ']' for array")
      }
      p = p.advance()
      (VArray(arr), p)
    }
    _ => raise TomlError::InvalidSyntax("unexpected token in value position")
  }
}

///|
fn parse_table_header(self : Parser) -> (Array[String], Parser) raise TomlError {
  // We've already seen '[', now parse the key path until ']'
  let mut p = self.advance() // skip '['
  let mut segments = []
  let first = parse_key_segment(p)
  let segment = first.0
  p = first.1
  segments.push(segment)
  while p.current() is Dot {
    p = p.advance()
    let result = parse_key_segment(p)
    let seg = result.0
    p = result.1
    segments.push(seg)
  }
  if p.current() isnot RBracket {
    raise TomlError::InvalidSyntax("expected ']' at end of table header")
  }
  p = p.advance()
  // Skip trailing whitespace/newlines
  p = p.skip_newlines()
  (segments, p)
}

///|
fn parse_key_segment(self : Parser) -> (String, Parser) raise TomlError {
  match self.current() {
    BareKey(s) => (s, self.advance())
    QuotedKey(s) => (s, self.advance())
    _ => raise TomlError::InvalidSyntax("expected key in table header or dotted key")
  }
}

///|
fn parse_key_path(self : Parser) -> (Array[String], Parser) raise TomlError {
  let mut segments = []
  let first = parse_key_segment(self)
  let seg = first.0
  let mut p = first.1
  segments.push(seg)
  while p.current() is Dot {
    p = p.advance()
    let result = parse_key_segment(p)
    let s = result.0
    p = result.1
    segments.push(s)
  }
  if p.current() isnot Equals {
    raise TomlError::InvalidSyntax("expected '=' after key")
  }
  p = p.advance()
  (segments, p)
}

///|
enum Line {
  Table(Array[String])
  KeyValue(Array[String], Value)
}

///|
fn parse_lines(self : Parser) -> Array[Line] raise TomlError {
  let mut p = self.skip_newlines()
  let mut lines = []
  while p.current() isnot EOF {
    match p.current() {
      Newline => {
        p = p.advance()
        p = p.skip_newlines()
      }
      LBracket => {
        // Check if it's a table or array-of-tables (we only support tables)
        p = p.advance()
        if p.current() is LBracket {
          raise TomlError::InvalidSyntax("array of tables not supported")
        }
        // Table header: go back and parse
        p = { tokens: p.tokens, pos: p.pos - 1 }
        let result = p.parse_table_header()
        let segments = result.0
        p = result.1
        lines.push(Table(segments))
      }
      BareKey(_) | QuotedKey(_) => {
        let result = p.parse_key_path()
        let key_segments = result.0
        p = result.1
        p = p.skip_newlines()
        let val_result = p.parse_value_from_parser()
        let value = val_result.0
        p = val_result.1
        lines.push(KeyValue(key_segments, value))
        // Skip trailing newlines
        p = p.skip_newlines()
      }
      _ => raise TomlError::InvalidSyntax("unexpected token at line start")
    }
  }
  lines
}

///| Public: build a Json object from parsed lines.
pub fn build_json(lines : Array[Line]) -> Json raise TomlError {
  let root : Map[String, Json] = {}
  let assigned_keys : Map[String, Bool] = {}
  let mut current_table : Array[String] = []

  for i = 0; i < lines.length(); i = i + 1 {
    match lines[i] {
      Table(segments) => {
        current_table = segments
        let table_key = join_path(segments)
        if assigned_keys.contains(table_key) {
          raise TomlError::DuplicateKey("duplicate table [\(table_key)]")
        }
        assigned_keys[table_key] = true
        // Ensure intermediate tables exist
        ensure_table(root, segments)
      }
      KeyValue(key_segments, value) => {
        // Build full path: current_table + key_segments
        let full_segments = current_table + key_segments
        let full_key = join_path(full_segments)
        if assigned_keys.contains(full_key) {
          raise TomlError::DuplicateKey("duplicate key '\(full_key)'")
        }
        assigned_keys[full_key] = true
        // Ensure all but last segment exist as tables
        let parent_segments = full_segments[0:full_segments.length() - 1]
        ensure_table(root, parent_segments)
        let last_key = full_segments[full_segments.length() - 1]
        let json_value = value_to_json(value)
        // Insert into the right place
        insert_value(root, parent_segments, last_key, json_value)
      }
    }
  }
  Json::object(root)
}

///|
fn join_path(segments : Array[String]) -> String {
  let buf = StringBuilder::new()
  for i = 0; i < segments.length(); i = i + 1 {
    if i > 0 {
      buf.put_char('.')
    }
    buf.put_string(segments[i])
  }
  buf.to_string()
}

///|
fn ensure_table(root : Map[String, Json], segments : Array[String]) {
  let mut current = root
  for i = 0; i < segments.length(); i = i + 1 {
    let seg = segments[i]
    match current[seg] {
      Json::Object(_) => {
        // Navigate into existing object
        match current[seg] {
          Json::Object(m) => current = m
          _ => {}
        }
      }
      _ => {
        let new_map : Map[String, Json] = {}
        current[seg] = Json::object(new_map)
        current = new_map
      }
    }
  }
}

///|
fn insert_value(
  root : Map[String, Json],
  parent_segments : Array[String],
  last_key : String,
  value : Json
) {
  let mut current = root
  for i = 0; i < parent_segments.length(); i = i + 1 {
    let seg = parent_segments[i]
    match current[seg] {
      Json::Object(m) => current = m
      _ => {
        let new_map : Map[String, Json] = {}
        current[seg] = Json::object(new_map)
        current = new_map
      }
    }
  }
  current[last_key] = value
}

///|
fn value_to_json(value : Value) -> Json {
  match value {
    VString(s) => Json::string(s)
    VInteger(n) => Json::number(n.to_double(), repr=n.to_string())
    VBoolean(b) => Json::boolean(b)
    VArray(arr) => {
      let json_arr = []
      for i = 0; i < arr.length(); i = i + 1 {
        json_arr.push(value_to_json(arr[i]))
      }
      Json::array(json_arr)
    }
  }
}
"}

{"path": "/private/tmp/prompt_matrix/runs_pro-x-flashprompt/workspaces/04/lib/toml.mbt", "content": "///| Public TOML library API.
///|
///| Parse TOML text into a deterministic JSON value.
pub fn parse(text : String) -> Json raise TomlError {
  let tokens = @lexer.lex(text)
  let parser = @parser.new_parser(tokens)
  let lines = parser.parse_lines()
  @parser.build_json(lines)
}
"}

