{"path": "/private/tmp/prompt_matrix/runs_pro-x-flashprompt/workspaces/04/lib/lexer.mbt", "content": "///| Lexer types — tokens produced from TOML source text.

///|
pub enum Token {
  BareKey(String)
  QuotedKey(String)
  Equals
  Dot
  LBracket
  RBracket
  String(String)
  Integer(Int64)
  Boolean(Bool)
  LBrace
  RBrace
  Comma
  Newline
  EOF
}

///|
pub fn lex(input : String) -> Array[Token] raise TomlError {
  let tokens = []
  let mut i = 0
  let len = input.length()
  while i < len {
    let c = input[i]
    if c == '\n' {
      tokens.push(Newline)
      i = i + 1
    } else if c == '\r' {
      if i + 1 < len && input[i + 1] == '\n' {
        i = i + 1
      }
      tokens.push(Newline)
      i = i + 1
    } else if c == ' ' || c == '\t' {
      // Skip whitespace between tokens (not newlines)
      i = i + 1
    } else if c == '#' {
      // Comment: skip to end of line
      let mut j = i + 1
      while j < len && input[j] != '\n' && input[j] != '\r' {
        j = j + 1
      }
      i = j
    } else if c == '=' {
      tokens.push(Equals)
      i = i + 1
    } else if c == '.' {
      tokens.push(Dot)
      i = i + 1
    } else if c == '[' {
      tokens.push(LBracket)
      i = i + 1
    } else if c == ']' {
      tokens.push(RBracket)
      i = i + 1
    } else if c == '{' {
      tokens.push(LBrace)
      i = i + 1
    } else if c == '}' {
      tokens.push(RBrace)
      i = i + 1
    } else if c == ',' {
      tokens.push(Comma)
      i = i + 1
    } else if c == '\"' {
      let result = lex_string(input, i)
      let s = result.0
      i = result.1
      tokens.push(String(s))
    } else if is_digit(c) || c == '+' || c == '-' {
      let result = lex_number(input, i)
      let n = result.0
      i = result.1
      tokens.push(Integer(n))
    } else if is_alpha(c) {
      let result = lex_ident(input, i)
      let ident = result.0
      i = result.1
      match ident {
        "true" => tokens.push(Boolean(true))
        "false" => tokens.push(Boolean(false))
        _ => tokens.push(BareKey(ident))
      }
    } else {
      raise TomlError::InvalidSyntax("unexpected character '\(input[i].to_string())' at position \(i)")
    }
  }
  tokens.push(EOF)
  tokens
}

///|
fn lex_string(input : String, start : Int) -> (String, Int) raise TomlError {
  let len = input.length()
  let mut i = start + 1
  let buf = StringBuilder::new()
  while i < len {
    let c = input[i]
    if c == '\"' {
      i = i + 1
      break
    } else if c == '\\' {
      i = i + 1
      if i >= len {
        raise TomlError::InvalidSyntax("unterminated string escape at position \(start)")
      }
      let escaped = input[i]
      match escaped {
        'n' => buf.put_char('\n')
        't' => buf.put_char('\t')
        '\\' => buf.put_char('\\')
        '\"' => buf.put_char('\"')
        _ => raise TomlError::InvalidSyntax("unknown escape sequence \\\(escaped.to_string()) at position \(i)")
      }
      i = i + 1
    } else if c == '\n' || c == '\r' {
      raise TomlError::InvalidSyntax("unterminated string at position \(start)")
    } else {
      buf.put_char(c.to_char())
      i = i + 1
    }
  }
  (buf.to_string(), i)
}

///|
fn is_digit(c : Char) -> Bool {
  c >= '0' && c <= '9'
}

///|
fn is_alpha(c : Char) -> Bool {
  (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_' || c == '-'
}

///|
fn is_alphanumeric(c : Char) -> Bool {
  is_alpha(c) || is_digit(c)
}

///|
fn lex_number(input : String, start : Int) -> (Int64, Int) raise TomlError {
  let len = input.length()
  let mut i = start
  let mut sign : Int64 = 1
  if input[i] == '+' {
    i = i + 1
  } else if input[i] == '-' {
    sign = -1
    i = i + 1
  }
  if i >= len || not(is_digit(input[i])) {
    raise TomlError::InvalidSyntax("expected digit at position \(i)")
  }
  let mut value : Int64 = 0
  while i < len && is_digit(input[i]) {
    let digit = (input[i].to_int() - '0'.to_int()).to_int64()
    value = value * 10 + digit
    i = i + 1
  }
  // Check for trailing alphanumeric (invalid: 123abc)
  if i < len && is_alphanumeric(input[i]) {
    raise TomlError::InvalidSyntax("invalid character after number at position \(i)")
  }
  (sign * value, i)
}

///|
fn lex_ident(input : String, start : Int) -> (String, Int) {
  let len = input.length()
  let mut i = start
  let buf = StringBuilder::new()
  while i < len && is_alphanumeric(input[i]) {
    buf.put_char(input[i].to_char())
    i = i + 1
  }
  (buf.to_string(), i)
}
