{"content": "///| TOML to JSON CLI converter.

///|
struct Config {
  input : String
  stdin : Bool
}

///|
async fn main {
  let config = @argparse.parse(
    Command(
      "tomljson",
      about="Convert TOML to JSON.",
      flags=[
        FlagArg("stdin", long="stdin", about="Read TOML from stdin."),
      ],
      positionals=[
        PositionArg("input", default_values=["-"], about="Input TOML file path."),
      ],
    ),
  ) |> config_from_matches

  let toml_text = if config.stdin {
    @stdio.stdin.read_all().text()
  } else {
    @fs.read_file(config.input).text()
  }

  let result = @lib.parse(toml_text)
  match result {
    json => {
      println(json.stringify())
    }
  }
  catch {
    @lib.TomlError::InvalidSyntax(msg) => {
      @stdio.stderr.write("tomljson: syntax error: \(msg)\n".to_bytes())
    }
    @lib.TomlError::DuplicateKey(msg) => {
      @stdio.stderr.write("tomljson: duplicate key: \(msg)\n".to_bytes())
    }
  }
}

///|
fn config_from_matches(matches : @argparse.Matches) -> Config raise {
  match matches {
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : Some(stdin), .. },
      ..,
    } => { input, stdin }
    {
      values: { "input"? : Some([input, ..]), .. },
      flags: { "stdin"? : None, .. },
      ..,
    } => {
      let stdin = false
      { input, stdin }
    }
    _ => fail("missing parsed argument: input")
  }
}
