///|
pub enum Token {
  BareKey(String)
  QuotedKey(String)
  Equals
  Dot
  LBracket
  RBracket
  String(String)
  Integer(Int64)
  Boolean(Bool)
  LBrace
  RBrace
  Comma
  Newline
  EOF
}

///|
pub fn lex(input : String) -> Array[Token] raise TomlError {
  let tokens = []
  let mut i = 0
  let len = input.char_length()
  while i < len {
    match input.get_char(i) {
      None => break
      Some(c) => {
        if c == '\n' {
          tokens.push(Newline)
          i = i + 1
        } else if c == '\r' {
          match input.get_char(i + 1) {
            Some('\n') => i = i + 1
            _ => ()
          }
          tokens.push(Newline)
          i = i + 1
        } else if c == ' ' || c == '\t' {
          i = i + 1
        } else if c == '#' {
          let mut j = i + 1
          while is_not_newline(input, j) {
            j = j + 1
          }
          i = j
        } else if c == '=' {
          tokens.push(Equals)
          i = i + 1
        } else if c == '.' {
          tokens.push(Dot)
          i = i + 1
        } else if c == '[' {
          tokens.push(LBracket)
          i = i + 1
        } else if c == ']' {
          tokens.push(RBracket)
          i = i + 1
        } else if c == '{' {
          tokens.push(LBrace)
          i = i + 1
        } else if c == '}' {
          tokens.push(RBrace)
          i = i + 1
        } else if c == ',' {
          tokens.push(Comma)
          i = i + 1
        } else if c == '\"' {
          let result = lex_string(input, i)
          let s = result.0
          i = result.1
          tokens.push(String(s))
        } else if is_digit(c) || c == '+' || c == '-' {
          let result = lex_number(input, i)
          let n = result.0
          i = result.1
          tokens.push(Integer(n))
        } else if is_alpha(c) {
          let result = lex_ident(input, i)
          let ident = result.0
          i = result.1
          match ident {
            "true" => tokens.push(Boolean(true))
            "false" => tokens.push(Boolean(false))
            _ => tokens.push(BareKey(ident))
          }
        } else {
          raise TomlError::InvalidSyntax("unexpected character '\{c}' at position \{i}")
        }
      }
    }
  }
  tokens.push(EOF)
  tokens
}

///|
fn is_not_newline(input : String, idx : Int) -> Bool {
  match input.get_char(idx) {
    Some('\n') | Some('\r') => false
    None => false
    _ => true
  }
}

///|
fn lex_string(input : String, start : Int) -> (String, Int) raise TomlError {
  let mut i = start + 1
  let len = input.char_length()
  let buf = StringBuilder::new()
  while i < len {
    match input.get_char(i) {
      None => break
      Some(c) => {
        if c == '\"' {
          i = i + 1
          break
        } else if c == '\\' {
          i = i + 1
          match input.get_char(i) {
            None => raise TomlError::InvalidSyntax("unterminated string escape at position \{start}")
            Some(escaped) => {
              match escaped {
                'n' => buf.write_char('\n')
                't' => buf.write_char('\t')
                '\\' => buf.write_char('\\')
                '\"' => buf.write_char('\"')
                _ => raise TomlError::InvalidSyntax("unknown escape sequence \\\{escaped} at position \{i}")
              }
              i = i + 1
            }
          }
        } else if c == '\n' || c == '\r' {
          raise TomlError::InvalidSyntax("unterminated string at position \{start}")
        } else {
          buf.write_char(c)
          i = i + 1
        }
      }
    }
  }
  (buf.to_string(), i)
}

///|
fn is_digit(c : Char) -> Bool {
  c >= '0' && c <= '9'
}

///|
fn is_alpha(c : Char) -> Bool {
  (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '_' || c == '-'
}

///|
fn is_alphanumeric(c : Char) -> Bool {
  is_alpha(c) || is_digit(c)
}

///|
fn lex_number(input : String, start : Int) -> (Int64, Int) raise TomlError {
  let len = input.char_length()
  let mut i = start
  let mut sign : Int64 = 1
  match input.get_char(i) {
    Some('+') => i = i + 1
    Some('-') => {
      sign = -1
      i = i + 1
    }
    _ => ()
  }
  let digits_buf = StringBuilder::new()
  while i < len {
    match input.get_char(i) {
      Some(c) => {
        if is_digit(c) {
          digits_buf.write_char(c)
          i = i + 1
        } else {
          break
        }
      }
      None => break
    }
  }
  let digits_str = digits_buf.to_string()
  if digits_str == "" {
    raise TomlError::InvalidSyntax("expected digit at position \{i}")
  }
  let value : Int64 = @string.from_str(digits_str) catch {
    _ => raise TomlError::InvalidSyntax("invalid integer at position \{start}")
  }
  let result = sign * value
  // Check for trailing alphanumeric
  match input.get_char(i) {
    Some(c) => {
      if is_alphanumeric(c) {
        raise TomlError::InvalidSyntax("invalid character after number at position \{i}")
      }
    }
    _ => ()
  }
  (result, i)
}

///|
fn lex_ident(input : String, start : Int) -> (String, Int) {
  let len = input.char_length()
  let mut i = start
  let buf = StringBuilder::new()
  while i < len {
    match input.get_char(i) {
      Some(c) => {
        if is_alphanumeric(c) {
          buf.write_char(c)
          i = i + 1
        } else {
          break
        }
      }
      None => break
    }
  }
  (buf.to_string(), i)
}
