///|
enum Value {
  VString(String)
  VInteger(Int64)
  VBoolean(Bool)
  VArray(Array[Value])
}

///|
struct Parser {
  tokens : Array[Token]
  pos : Int
}

///|
fn new_parser(tokens : Array[Token]) -> Parser {
  { tokens, pos: 0 }
}

///|
fn current(self : Parser) -> Token {
  self.tokens[self.pos]
}

///|
fn advance(self : Parser) -> Parser {
  { tokens: self.tokens, pos: self.pos + 1 }
}

///|
fn skip_newlines(self : Parser) -> Parser {
  let mut p = self
  while match_token_kind(p.current(), Newline) {
    p = p.advance()
  }
  p
}

///|
fn match_token_kind(tok : Token, kind : Token) -> Bool {
  match (tok, kind) {
    (Newline, Newline) => true
    (RBracket, RBracket) => true
    (RBrace, RBrace) => true
    (EOF, EOF) => true
    (Dot, Dot) => true
    (Equals, Equals) => true
    (Comma, Comma) => true
    (LBracket, LBracket) => true
    _ => match tok {
      Newline => false
      RBracket => false
      RBrace => false
      EOF => false
      Dot => false
      Equals => false
      Comma => false
      LBracket => false
      _ => false
    }
  }
}

///|
fn parse_value_from_parser(self : Parser) -> (Value, Parser) raise TomlError {
  let tok = self.current()
  match tok {
    String(s) => (VString(s), self.advance())
    Integer(n) => (VInteger(n), self.advance())
    Boolean(b) => (VBoolean(b), self.advance())
    LBracket => {
      let mut p = self.advance()
      let arr : Array[Value] = []
      p = p.skip_newlines()
      while is_not_rbracket_or_eof(p) {
        let result = parse_value_from_parser(p)
        let v = result.0
        p = result.1
        arr.push(v)
        p = p.skip_newlines()
        match p.current() {
          Comma => {
            p = p.advance()
            p = p.skip_newlines()
          }
          _ => break
