{"content": "///| Parser: converts a token stream into a JSON value via line-oriented TOML parsing.

///|
enum Value {
  VString(String)
  VInteger(Int64)
  VBoolean(Bool)
  VArray(Array[Value])
}

///|
struct Parser {
  tokens : Array[Token]
  pos : Int
}

///|
pub fn Parser::new(tokens : Array[Token]) -> Parser {
  { tokens, pos: 0 }
}

///|
fn Parser::current(self : Parser) -> Token {
  self.tokens[self.pos]
}

///|
fn Parser::advance(self : Parser) -> Parser {
  { tokens: self.tokens, pos: self.pos + 1 }
}

///|
fn Parser::skip_newlines(self : Parser) -> Parser {
  let mut p = self
  while match_token_kind(p.current(), Newline) {
    p = p.advance()
  }
  p
}

///|
fn match_token_kind(tok : Token, kind : Token) -> Bool {
  match (tok, kind) {
    (Newline, Newline) => true
    (RBracket, RBracket) => true
    (RBrace, RBrace) => true
    (EOF, EOF) => true
    (Dot, Dot) => true
    (Equals, Equals) => true
    (Comma, Comma) => true
    (LBracket, LBracket) => true
    _ => match tok {
      Newline => false
      RBracket => false
      RBrace => false
      EOF => false
      Dot => false
      Equals => false
      Comma => false
      LBracket => false
      _ => false
    }
  }
}

///|
fn Parser::parse_value(self : Parser) -> (Value, Parser) raise TomlError {
  let tok = self.current()
  match tok {
    String(s) => (VString(s), self.advance())
    Integer(n) => (VInteger(n), self.advance())
    Boolean(b) => (VBoolean(b), self.advance())
    LBracket => {
      let mut p = self.advance()
      let arr : Array[Value] = []
      p = p.skip_newlines()
      while is_not_rbracket_or_eof(p) {
        let result = p.parse_value()
        let v = result.0
        p = result.1
        arr.push(v)
        p = p.skip_newlines()
        match p.current() {
          Comma => {
            p = p.advance()
            p = p.skip_newlines()
          }
          _ => break
        }
      }
      if !is_token(p.current(), RBracket) {
        raise TomlError::InvalidSyntax("expected ']' for array")
      }
      p = p.advance()
      (VArray(arr), p)
    }
    _ => raise TomlError::InvalidSyntax("unexpected token in value position")
  }
}

///|
fn is_not_rbracket_or_eof(p : Parser) -> Bool {
  let tok = p.current()
  !(is_token(tok, RBracket) || is_token(tok, EOF))
}

///|
fn is_token(tok : Token, kind : Token) -> Bool {
  match tok {
    LBracket => match kind {
      LBracket => true
      _ => false
    }
    RBracket => match kind {
      RBracket => true
      _ => false
    }
    RBrace => match kind {
      RBrace => true
      _ => false
    }
    EOF => match kind {
      EOF => true
      _ => false
    }
    Newline => match kind {
      Newline => true
      _ => false
    }
    Dot => match kind {
      Dot => true
      _ => false
    }
    Equals => match kind {
      Equals => true
      _ => false
    }
    Comma => match kind {
      Comma => true
      _ => false
    }
    BareKey(_) | QuotedKey(_) | String(_) | Integer(_) | Boolean(_) => false
  }
}

///|
fn Parser::parse_table_header(self : Parser) -> (Array[String], Parser) raise TomlError {
  let mut p = self.advance()
  let segments : Array[String] = []
  let first = p.parse_key_segment()
  let segment = first.0
  p = first.1
  segments.push(segment)
  while is_token(p.current(), Dot) {
    p = p.advance()
    let result = p.parse_key_segment()
    let seg = result.0
    p = result.1
    segments.push(seg)
  }
  if !is_token(p.current(), RBracket) {
    raise TomlError::InvalidSyntax("expected ']' at end of table header")
  }
  p = p.advance()
  p = p.skip_newlines()
  (segments, p)
}

///|
fn Parser::parse_key_segment(self : Parser) -> (String, Parser) raise TomlError {
  match self.current() {
    BareKey(s) => (s, self.advance())
    QuotedKey(s) => (s, self.advance())
    _ => raise TomlError::InvalidSyntax("expected key")
  }
}

///|
fn Parser::parse_key_path(self : Parser) -> (Array[String], Parser) raise TomlError {
  let segments : Array[String] = []
  let first = self.parse_key_segment()
  let seg = first.0
  let mut p = first.1
  segments.push(seg)
  while is_token(p.current(), Dot) {
    p = p.advance()
    let result = p.parse_key_segment()
    let s = result.0
    p = result.1
    segments.push(s)
  }
  if !is_token(p.current(), Equals) {
    raise TomlError::InvalidSyntax("expected '=' after key")
  }
  p = p.advance()
  (segments, p)
}

///|
enum Line {
  Table(Array[String])
  KeyValue(Array[String], Value)
}

///|
pub fn Parser::parse_lines(self : Parser) -> Array[Line] raise TomlError {
  let mut p = self.skip_newlines()
  let lines : Array[Line] = []
  while !is_token(p.current(), EOF) {
    match p.current() {
      Newline => {
        p = p.advance()
        p = p.skip_newlines()
      }
      LBracket => {
        p = p.advance()
        if is_token(p.current(), LBracket) {
          raise TomlError::InvalidSyntax("array of tables not supported")
        }
        p = { tokens: p.tokens, pos: p.pos - 1 }
        let result = p.parse_table_header()
        let segments = result.0
        p = result.1
        lines.push(Table(segments))
      }
      BareKey(_) | QuotedKey(_) => {
        let result = p.parse_key_path()
        let key_segments = result.0
        p = result.1
        p = p.skip_newlines()
        let val_result = p.parse_value()
        let value = val_result.0
        p = val_result.1
        lines.push(KeyValue(key_segments, value))
        p = p.skip_newlines()
      }
      _ => raise TomlError::InvalidSyntax("unexpected token at line start")
    }
  }
  lines
}

///| Build a Json object from parsed lines.
pub fn build_json(lines : Array[Line]) -> Json raise TomlError {
  let root : Map[String, Json] = {}
  let assigned_keys : Map[String, Bool] = {}
  let mut current_table : Array[String] = []

  for i = 0; i < lines.length(); i = i + 1 {
    match lines[i] {
      Table(segments) => {
        current_table = segments
        let table_key = join_path(segments)
        if assigned_keys.contains(table_key) {
          raise TomlError::DuplicateKey("duplicate table [\{table_key}]")
        }
        assigned_keys[table_key] = true
        ensure_table(root, segments)
      }
      KeyValue(key_segments, value) => {
        let full_segments = concat_arrays(current_table, key_segments)
        let full_key = join_path(full_segments)
        if assigned_keys.contains(full_key) {
          raise TomlError::DuplicateKey("duplicate key '\{full_key}'")
        }
        assigned_keys[full_key] = true
        let parent_segments = slice_array(full_segments, 0, full_segments.length() - 1)
        ensure_table(root, parent_segments)
        let last_key = full_segments[full_segments.length() - 1]
        let json_value = value_to_json(value)
        insert_value(root, parent_segments, last_key, json_value)
      }
    }
  }
  Json::object(root)
}

///|
fn concat_arrays(a : Array[String], b : Array[String]) -> Array[String] {
  let result : Array[String] = []
  for i = 0; i < a.length(); i = i + 1 {
    result.push(a[i])
  }
  for i = 0; i < b.length(); i = i + 1 {
    result.push(b[i])
  }
  result
}

///|
fn slice_array(arr : Array[String], start : Int, end : Int) -> Array[String] {
  let result : Array[String] = []
  for i = start; i < end; i = i + 1 {
    result.push(arr[i])
  }
  result
}

///|
fn join_path(segments : Array[String]) -> String {
  let buf = StringBuilder::new()
  for i = 0; i < segments.length(); i = i + 1 {
    if i > 0 {
      buf.write_char('.')
    }
    buf.write_string(segments[i])
  }
  buf.to_string()
}

///|
fn ensure_table(root : Map[String, Json], segments : Array[String]) -> Unit {
  let mut current = root
  for i = 0; i < segments.length(); i = i + 1 {
    let seg = segments[i]
    match current[seg] {
      Json::Object(_) => {
        match current[seg] {
          Json::Object(m) => current = m
          _ => ()
        }
      }
      _ => {
        let new_map : Map[String, Json] = {}
        current[seg] = Json::object(new_map)
        current = new_map
      }
    }
  }
}

///|
fn insert_value(
  root : Map[String, Json],
  parent_segments : Array[String],
  last_key : String,
  value : Json
) -> Unit {
  let mut current = root
  for i = 0; i < parent_segments.length(); i = i + 1 {
    let seg = parent_segments[i]
    match current[seg] {
      Json::Object(m) => current = m
      _ => {
        let new_map : Map[String, Json] = {}
        current[seg] = Json::object(new_map)
        current = new_map
      }
    }
  }
  current[last_key] = value
}

///|
fn value_to_json(value : Value) -> Json {
  match value {
    VString(s) => Json::string(s)
    VInteger(n) => {
      let repr = n.to_string()
      Json::number(n.to_double(), repr=repr)
    }
    VBoolean(b) => Json::boolean(b)
    VArray(arr) => {
      let json_arr : Array[Json] = []
      for i = 0; i < arr.length(); i = i + 1 {
        json_arr.push(value_to_json(arr[i]))
      }
      Json::array(json_arr)
    }
  }
}
