{"content": "///| TOML to JSON CLI converter.

///|
struct Config {
  input : String
  stdin : Bool
}

///|
async fn main {
  let config = parse_args()
  let toml_text = if config.stdin {
    @stdio.stdin.read_all().text()
  } else {
    @fs.read_file(config.input).text()
  }

  try {
    let json = @lib.parse(toml_text)
    println(json.stringify())
  } catch {
    @lib.TomlError::InvalidSyntax(msg) => {
      @stdio.stderr.write("tomljson: syntax error: \{msg}\n".to_bytes())
    }
    @lib.TomlError::DuplicateKey(msg) => {
      @stdio.stderr.write("tomljson: duplicate key: \{msg}\n".to_bytes())
    }
  }
}

///|
fn parse_args() -> Config {
  let args = @env.args()
  let mut stdin = false
  let mut input = "-"
  for i = 0; i < args.length(); i = i + 1 {
    if args[i] == "--stdin" {
      stdin = true
    } else if i > 0 {
      input = args[i]
    }
  }
  { input, stdin }
}
